  }
}

// i ist die Nummer des angeklickten Knopfs (0, 1 oder 2)
function antworte(i) {
  const f = fragen[nummer];
  if (i === f.richtig) {
    anzeige.textContent = 'Richtig!';
    punkte++;
    stand.textContent = 'Punkte: ' + punkte;
  } else {
    anzeige.textContent = 'Falsch! Richtig wäre: ' + f.antworten[f.richtig];
  }
  nummer++;
  if (nummer < fragen.length) {
    zeigeFrage();
  } else {
    zeigeAuswertung();
  }
}

// Macht aus dem Punktestand einen Kommentar
function bewertung(richtige, anzahl) {
  if (richtige === anzahl) return 'Perfekt!';
  if (richtige >= anzahl / 2) return 'Gut gemacht!';
  return 'Übe noch ein bisschen!';
}

// Wird nach der letzten Frage aufgerufen
function zeigeAuswertung() {
  ueberschrift.textContent = 'Auswertung';
  text.textContent = 'Du hast ' + punkte + ' von ' + fragen.length + ' Punkten. ' + bewertung(punkte, fragen.length);
  for (const k of knoepfe) {
    k.hidden = true;
  }
  knopf.hidden = false; // jetzt darf man nochmal spielen
}

// Setzt alles auf Anfang – beim ersten Start und bei jedem Klick auf 'Nochmal spielen'
function neuStart() {
  nummer = 0;
  punkte = 0;
  ueberschrift.textContent = 'Bunt gemischt';
  anzeige.textContent = '';
  stand.textContent = 'Punkte: ' + punkte;
  for (const k of knoepfe) {
    k.hidden = false;
  }
  knopf.hidden = true;
  zeigeFrage();
}

knopf.textContent = 'Nochmal spielen';
knopf.addEventListener('click', neuStart);
neuStart();
